import{z as s,x as l,o as e,c as p,q as r,j as i,D as a,d as t,s as A,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"承诺装置","description":"","frontmatter":{"title":"承诺装置","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/commitment-devices.md","filePath":"econ/commitment-devices.md","lastUpdated":1791063341000}'),d={name:"econ/commitment-devices.md"};function m(D,E,c,h,C,f){const n=l("Mermaid");return e(),p("div",null,[E[2]||(E[2]=r('<h1 id="承诺装置" tabindex="-1">承诺装置 <a class="header-anchor" href="#承诺装置" aria-label="Permalink to &quot;承诺装置&quot;">​</a></h1><div class="epigraph"><p>若未来的自己会改计划，有价值的不是更多选择，而是现在把某些选择关掉。</p><footer>—— Strotz, Myopia and Inconsistency in Dynamic Utility Maximization, RES 1955–56；Laibson, QJE 1997；对照 Thaler and Shefrin, AER 1981</footer></div><p><a href="/econ/hyperbolic-present-bias">上一课</a>给出准双曲与老练自我。本课缺口是：老练知道会偏，于是需求<strong>承诺</strong>——非流动性、默认缴存、合约罚则——把未来菜单缩小。不重写 \\(\\beta\\)–\\(\\delta\\)，只问装置如何进入预算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指数贴现下，更多选择弱优于更少（在无摩擦菜单上）。准双曲下这句话失败：未来菜单里若含「立刻吃掉储蓄」，老练的长期自我宁愿今天就看不见这个选项。缺口因此不是再定义偏好，而是承认<strong>约束可以是被需求的</strong>。这与显示偏好课的「选择揭示排序」不矛盾：被关掉的选项从未进入当期菜单，谈不上揭示。</p><p><span class="marginnote">直觉类比：尤利西斯知道自己听到海妖歌声会跳海，于是事先让水手把自己绑在桅杆上、并用蜡封住他们的耳朵。他不是不想听歌，而是<strong>预见到未来的自己会失控</strong>，所以提前花成本取消「跳海」这个选项。承诺装置就是给自己绑的缆绳：锁定期、违约金、默认缴存，都是现代版桅杆。</span></p><p>也不要把承诺写成限价簿上的撤单限制。这里没有队列；装置是家庭资产负债表与合约条款。</p><p><span class="marginnote">幼稚自我不买承诺：他们以为未来会执行。观测到的承诺需求是老练程度的证据，不是贴现率本身的测量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Strotz 的策略是事先限制未来可行集。Thaler 与 Shefrin（1981）的计划者–执行者：长期自我选约束，短期自我在约束内花钱。Laibson 的金蛋：非流动资产在下一期才能变现，现时自我无法把它变成即期消费，于是均衡持有金蛋，哪怕其回报并不高。Ashraf、Karlan 与 Yin（2006）在田间提供不可提前支取的储蓄账户，需求来自意识到现时偏差的人。</p><p>承诺可以是市场的（定期存款、住房首付），也可以是制度的（养老金默认、强制年金）。本课先钉「缩小菜单有正价值」，具体生命周期与年金谜后课再接。</p><p><span class="marginnote">数字实例：Ashraf–Karlan–Yin 的 SEED 账户年息与其他存款相当，唯一区别是 6 个月内不能取。结果：被邀请的人里约 28% 自愿开通，一年后其储蓄余额显著上升。同一利率却有人抢着要「不流动性」——正是「缩小菜单本身有价值」最干净的现场证据。</span></p>',12)),(e(),i(o,null,{default:a(()=>[A(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PB%5B%22%E7%8E%B0%E6%97%B6%E5%81%8F%E5%B7%AE%3A%20%E6%9C%AA%E6%9D%A5%E4%BC%9A%E6%94%B9%E8%AE%A1%E5%88%92%22%5D%20--%3E%20DEM%5B%22%E8%80%81%E7%BB%83%E9%9C%80%E6%B1%82%3A%20%E5%85%B3%E6%8E%89%E9%80%89%E6%8B%A9%22%5D%0A%20%20DEM%20--%3E%20ILL%5B%22%E9%9D%9E%E6%B5%81%E5%8A%A8%E8%B5%84%E4%BA%A7%20%2F%20%E9%87%91%E8%9B%8B%22%5D%0A%20%20DEM%20--%3E%20DEF%5B%22%E9%BB%98%E8%AE%A4%E4%B8%8E%E5%90%88%E7%BA%A6%E7%BD%9A%E5%88%99%22%5D%0A%20%20ILL%20--%3E%20EQ%5B%22%E5%9D%87%E8%A1%A1%3A%20%E6%8C%81%E6%9C%89%E4%BD%8E%E6%B5%81%E5%8A%A8%E5%B7%A5%E5%85%B7%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[t("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"机制是改变未来自我的可行集，从而改变子博弈完美均衡。提高提款成本、拉长锁定期、把边际储蓄设成默认，都是把 \\(c_{t+1}\\) 的上界或价格改掉。计划者并不需要改变 \\(\\beta\\)，只需要改变预算。这与宏观里「规则而非权变」同构但对象不同：那里绑的是政府，这里绑的是下一期的自己。",-1)),(e(),i(o,null,{default:a(()=>[A(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20T0%5B%22%E4%BB%8A%E5%A4%A9%EF%BC%9A%E8%AE%A1%E5%88%92%E8%80%85%E4%B9%B0%E5%85%A5%E5%AE%9A%E6%9C%9F%E5%AD%98%E6%AC%BE%22%5D%20--%3E%20T1%5B%22%E5%8F%91%E8%96%AA%E6%97%A5%EF%BC%9A%E5%8D%B3%E6%9C%9F%E8%87%AA%E6%88%91%E6%83%B3%E5%8F%96%E9%92%B1%E6%B6%88%E8%B4%B9%22%5D%0A%20%20T1%20--%3E%20LOCK%5B%22%E5%8F%96%E4%B8%8D%E5%87%BA%EF%BC%9A%E8%A6%81%E7%AD%89%E5%88%B0%E6%9C%9F%EF%BC%8C%E8%BF%9D%E7%BA%A6%E8%BF%98%E6%9C%89%E7%BD%9A%E6%81%AF%22%5D%0A%20%20LOCK%20--%3E%20SAVE%5B%22%E5%82%A8%E8%93%84%E4%BF%9D%E4%BD%8F%EF%BC%9A%E8%8F%9C%E5%8D%95%E9%87%8C%E6%B2%A1%E6%9C%89%E3%80%8C%E7%AB%8B%E5%88%BB%E8%8A%B1%E5%85%89%E3%80%8D%22%5D%0A%20%20T0%20--%3E%20ALT%5B%22%E4%B8%8D%E9%94%81%EF%BC%9A%E5%90%8C%E6%A0%B7%E4%B8%80%E7%AC%94%E9%92%B1%E6%94%BE%E6%B4%BB%E6%9C%9F%22%5D%0A%20%20ALT%20--%3E%20SPENT%5B%22%E5%8D%B3%E6%9C%9F%E8%87%AA%E6%88%91%E9%A1%BA%E6%89%8B%E8%8A%B1%E6%8E%89%22%5D%0A%20%20SPENT%20--%3E%20SORRY%5B%22%E5%B9%B4%E5%BA%95%E4%BD%99%E9%A2%9D%E4%B8%BA%E9%9B%B6%EF%BC%9A%E6%97%B6%E9%97%B4%E4%B8%8D%E4%B8%80%E8%87%B4%E7%9A%84%E4%BB%A3%E4%BB%B7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">常见误区：把存不下钱一律归因于「不懂理财知识」，于是开课教算术就完事。承诺模型给出的诊断不同：很多人<strong>明知</strong>该存，只是预见到明天的自己会破戒。对这类人，有效的干预不是再讲一遍复利，而是改变选项结构——把储蓄设成默认、把取钱变贵。知识提升 \\(\\beta\\) 的效果有限，装置根本不依赖 \\(\\beta\\) 变化。</span></p><p>代价是流动性损失与冲击到来时的再融资成本。承诺过度会在收入风险下后悔——预防性储蓄与流动性约束是后课，本课只标出权衡：现时偏差要锁，风险要留一扇门。</p><p>与宏观政策课的承诺不是同一合同：Kydland–Prescott 绑的是政府，面对的是私人预期；这里绑的是下一期的自己，面对的是同一人的 \\(\\beta\\)。工具可以长得像（规则、锁定期），对象必须分开写。默认缴存是后课素养与助推的接口，本课只要求：老练自我愿意为缩小菜单付正价格。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不是所有非流动性都是承诺。交易成本、信息不对称、住房的消费服务，都会产生不流动，不必有双曲。识别承诺需求要看：人是否愿意为「不能提前取」付正价格。本课不估计该价格，不把助推课提前写完。</p><p>后课默认：生命周期与储蓄制度可以当承诺读，但先要有一个时间一致或准双曲的计划，才知道锁的是哪一种自我。</p><p>承诺需求识别的是老练程度：愿意为不能提前取付正价格。幼稚自我会拒绝同一合同。</p><p>后课把养老金默认、住房首付和年金加载都当成候选装置，先要分清锁的是流动性还是自我。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>现时偏差下，关掉未来选择可以是需求，不是缺陷。</li><li>金蛋、锁定期、默认缴存，改的是可行集，不是 \\(\\beta\\)。</li><li>幼稚不买承诺；观测到的装置是老练的线索。</li><li>装置改可行集，不改贴现参数本身。</li><li>与政策承诺同构，对象是下一期的自己。</li><li>出处：Strotz, <em>RES</em> 1955–56；Thaler and Shefrin, <em>AER</em> 1981；Laibson, <em>QJE</em> 1997；Ashraf, Karlan and Yin, <em>QJE</em> 2006。</li></ul>',10))])}const T=s(d,[["render",m]]);export{b as __pageData,T as default};
